let deferredInstallPrompt=null;function isStandaloneDisplay(){return window.matchMedia(`(display-mode: standalone)`).matches||window.navigator.standalone===true}function isIOSDevice(){const isIOSUA=/iPad|iPhone|iPod/.test(navigator.userAgent);const isIPadOS13Plus=navigator.platform===`MacIntel`&&navigator.maxTouchPoints>1;return(isIOSUA||isIPadOS13Plus)&&!window.MSStream}window.addEventListener(`beforeinstallprompt`,e=>{e.preventDefault();deferredInstallPrompt=e;updateInstallUI();updateInstallHeaderBtn()});window.addEventListener(`appinstalled`,()=>{deferredInstallPrompt=null;updateInstallUI();updateInstallHeaderBtn();showToast(`Kinet est installé`);logEvent(`pwa_install`)});async function handleInstallClick(){if(!deferredInstallPrompt)return;deferredInstallPrompt.prompt();await deferredInstallPrompt.userChoice;deferredInstallPrompt=null;updateInstallUI();updateInstallHeaderBtn()}function updateInstallUI(){const el=document.getElementById(`installSectionContent`);if(!el)return;if(isStandaloneDisplay()){el.innerHTML=`<div class="wl-note">✓ Déjà installée sur cet appareil.</div>`;return}if(deferredInstallPrompt){el.innerHTML=`
      <div class="wl-note">Ajoute Kinet à ton écran d'accueil ou ton bureau. Ça s'ouvre comme une vraie app, plein écran, sans passer par le navigateur.</div>
      <button class="btn secondary" id="installNowBtn" type="button">Installer l'app</button>
    `;document.getElementById(`installNowBtn`).addEventListener(`click`,handleInstallClick);return}if(isIOSDevice()){el.innerHTML=`<div class="wl-note">Sur iPhone/iPad : bouton <b>Partager</b> de Safari (le carré avec la flèche vers le haut), puis <b>Sur l'écran d'accueil</b>.</div>`;return}el.innerHTML=`<div class="wl-note">Ton navigateur ne propose pas encore l'installation ici. Essaie avec Chrome ou Edge (téléphone ou PC), ou reviens dans quelques instants.</div>`}function updateInstallHeaderBtn(){const btn=document.getElementById(`installHeaderBtn`);if(!btn)return;btn.style.display=!isStandaloneDisplay()&&(deferredInstallPrompt||isIOSDevice())?``:`none`}document.getElementById(`installHeaderBtn`).addEventListener(`click`,()=>{if(deferredInstallPrompt)handleInstallClick();else if(isIOSDevice())showToast(`Bouton Partager de Safari, puis "Sur l'écran d'accueil"`)});updateInstallHeaderBtn();